SELECT FROM workflow_definition WHERE workspace_id = #{workspaceId}
AND status = 'ACTIVE' AND published_version_id IS NULL
AND status = 'ACTIVE' AND published_version_id IS NOT NULL
AND status = 'DISABLED'
ORDER BY updated_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE workflow_definition
SET name = #{definition.name},
    description = #{definition.description},
    version = version + 1,
    updated_at = #{definition.updatedAt}
WHERE id = #{definition.id}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'

UPDATE workflow_definition
SET status = 'DISABLED',
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'ACTIVE'
